The wave1 probe implemented sendControl/readFrame for the control socket; the secret servers accept a connection and reply with a framed JSON. Let me implement `fetchFrame(port)`:

```js
function fetchFrame(port) {
  return new Promise((resolve, reject) => {
    const socket = connectSocket({ host: "127.0.0.1", port })
    let buffer = Buffer.alloc(0)
    socket.on("data", chunk => {
      buffer = Buffer.concat([buffer, chunk])
      if (buffer.length < 4) return
      const length = buffer.readUInt32BE(0)
      if (buffer.length < length + 4) return
      const frame = Buffer.from(buffer.subarray(4, length + 4))
      socket.end()
      resolve(JSON.parse(frame.toString("utf8")))
      frame.fill(0)
    })
    socket.once("error", reject)
  })
}
```
Also create servers for ISSUE_OWNER_BOOTSTRAP and ISSUE_LOCAL_TOKEN:
```js
function secretRelay(controlSocket, command) {
  return new Promise((resolve, reject) => {
    const server = createServer(socket => {
      (async () => {
        const frame = await sendControl(controlSocket, { command })
        // patch managementUrl
        const value = JSON.parse(frame.toString("utf8"))
        value.managementUrl = relayOrigin
        const outgoing = Buffer.from(JSON.stringify(value), "utf8")
        const header = Buffer.alloc(4); header.writeUInt32BE(outgoing.length)
        socket.end(Buffer.concat([header, outgoing]))
      })().catch(error => socket.destroy(error))
    })
    server.listen(0, "127.0.0.1", () => resolve(server))
  })
}
```
Note the owner bootstrap needs managementUrl=relayOrigin; the local token one probably doesn't matter.

